module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter JR = 6'b001000,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

    reg [32:0] res;
    wire [31:0] signed_a;
    wire [31:0] signed_b;
    assign signed_a = a;
    assign signed_b = b;
    assign r = res[31:0];
    assign flag = (aluc == SLT || aluc == SLTU) ? ((aluc == SLT) ? ($signed(a) < $signed(b)) : (a < b)) : 1'b0;
    assign zero = (res[31:0] == 0) ? 1'b1 : 1'b0;
    assign negative = res[31];
    assign overflow = (aluc == ADD || aluc == ADDU) ? (res[32] != res[31]) : 1'b0;
    always @(*) begin
        case(aluc)
            ADD: begin
                res = $signed(signed_a) + $signed(signed_b);
                carry = res[32];
            end
            ADDU: begin
                res = signed_a + signed_b;
                carry = res[32];
            end
            SUB: begin
                res = $signed(signed_a) - $signed(signed_b);
                carry = res[32];
            end
            SUBU: begin
                res = signed_a - signed_b;
                carry = res[32];
            end
            AND: res = signed_a & signed_b;
            OR: res = signed_a | signed_b;
            XOR: res = signed_a ^ signed_b;
            NOR: res = ~(signed_a | signed_b);
            SLT: res = ($signed(signed_a) < $signed(signed_b)) ? 33'b1 : 33'b0;
            SLTU: res = (signed_a < signed_b) ? 33'b1 : 33'b0;
            SLL: res = signed_b << a[4:0];
            SRL: res = signed_b >> a[4:0];
            SRA: res = signed_b >>> a[4:0];
            SLLV: res = signed_b << a[4:0];
            SRLV: res = signed_b >> a[4:0];
            SRAV: res = signed_b >>> a[4:0];
            LUI: res = {a[15:0], 16'b0};
            default: res = 33'b0;
        endcase
    end

endmodule
